        try(var reader=new AsyncByteInspection((captured,page,cancelled,p)->{check(Thread.currentThread()!=caller && Thread.currentThread().isDaemon(),"off-UI daemon worker");calls.add(page);maximumActive.accumulateAndGet(active.incrementAndGet(),Math::max);try{if(page==0){entered.countDown();uninterruptible(release);Thread.interrupted();}return ByteInspection.inspect(captured,page,()->false,p);}finally{active.decrementAndGet();}},r->new Thread(r,"byte-latest-test"))){
            reader.start(pack,"objects/all.iob");await(entered);reader.page(pack,"objects/all.iob",1);var latest=reader.page(pack,"objects/all.iob",2);release.countDown();var state=ready(reader,pack,"objects/all.iob");check(state.request()==latest.request() && state.window().page()==2 && calls.equals(List.of(0,2)) && maximumActive.get()==1,"one active/latest pending and stale outcome rejection");
        }finally{release.countDown();}
